#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

void win(void) {
    char flag[64];
    FILE *f = fopen("flag.txt", "r");
    if (!f) { puts("flag.txt не найден"); exit(1); }
    fgets(flag, sizeof flag, f);
    puts(flag);
    exit(0);
}

int main(void) {
    char buf[32];
    setvbuf(stdout, NULL, _IONBF, 0);
    puts("Как тебя зовут?");
    read(0, buf, 0x100);
    puts("Пока!");
    return 0;
}
